/*
 * A341992  Take a standard 6-sided die and concatenate the numbers that can
 *          be seen around any of the corners and sort into increasing order.
 * https://oeis.org/A341992
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full
 * Formula:   a(n) is the nth smallest 3‑digit number composed of distinct
 *            digits 1..6 such that no two of the digits sum to 7. The
 *            sequence has 48 terms. It is generated by enumerating all
 *            permutations of three distinct digits 1..6 and selecting those
 *            that satisfy the pairwise-sum constraint
 * Range:     u8 none, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

static int cmp_seq_t(const void *p1, const void *p2)
{
    const seq_t *x = (const seq_t *)p1;
    const seq_t *y = (const seq_t *)p2;
    if (*x < *y) return -1;
    if (*x > *y) return 1;
    return 0;
}

seq_t a(idx_t n)
{
    /* Static table of sorted values, filled on first use. */
    static seq_t table[48];
    static bool ready = false;

    if (!ready) {
        /* Enumerate all ordered triples of distinct digits 1..6. */
        size_t pos = 0;
        for (idx_t i = 1; i <= 6; ++i) {
            for (idx_t j = 1; j <= 6; ++j) {
                if (j == i) continue;
                for (idx_t k = 1; k <= 6; ++k) {
                    if (k == i || k == j) continue;
                    /* Disallow pairs that sum to 7. */
                    if (i + j == 7 || i + k == 7 || j + k == 7) continue;
                    table[pos++] = (seq_t)i * 100 + (seq_t)j * 10 + (seq_t)k;
                }
            }
        }
        /* pos should be 48 after the loops. */
        qsort(table, pos, sizeof(seq_t), cmp_seq_t);
        ready = true;
    }

    if (n < 1 || n > 48) return 0;   /* undefined outside the range */
    return table[(size_t)(n - 1)];
}
